export const STUDIO_VERSION=1;
export const FORMATS={portrait:{label:'Portrait',w:600,h:800,exportW:1080,exportH:1440},square:{label:'Square',w:600,h:600,exportW:1080,exportH:1080},story:{label:'Story',w:600,h:1066.6667,exportW:1080,exportH:1920},small:{label:'Small',w:300,h:300},medium:{label:'Medium',w:600,h:300},large:{label:'Large',w:600,h:630}};
export const PRESETS=[{id:'white',name:'Pure white',colors:['#FFFFFF','#FFFFFF','#FFFFFF'],intensity:100,third:false},{id:'sky',name:'Soft sky',colors:['#FFFFFF','#C4DFF0','#E3EDDF'],intensity:70,third:true},{id:'garden',name:'Quiet garden',colors:['#FFFFFF','#D6E4CD','#E1EDF4'],intensity:70,third:true},{id:'rose',name:'Rose mist',colors:['#FFFFFF','#EBD6DC','#DEEAF2'],intensity:65,third:true},{id:'night',name:'Evening',colors:['#132029','#344E62','#596D63'],intensity:100,third:true}];
export const INKS=[['Ink','#111111'],['White','#FFFFFF'],['Slate','#526D82'],['Olive','#506554'],['Rose','#8C5B6B']];
export const FONTS={baskerville:{label:'Baskerville',css:'Baskerville, Georgia, serif'},italic:{label:'Baskerville Italic',css:'Baskerville, Georgia, serif',italic:true},avenir:{label:'Avenir Next',css:'"Avenir Next", Avenir, sans-serif'},dm:{label:'DM Sans',css:'"DM Sans", sans-serif'}};
export const clamp=(n,min,max)=>Math.min(max,Math.max(min,Number(n)||0));
export function defaultDesign(kind){return {version:1,kind,format:kind==='widget'?'medium':'portrait',background:'gradient',colors:['#FFFFFF','#DDEADA','#DCECF5'],third:true,intensity:70,angle:155,photoId:null,photoShade:18,photoFocus:50,color:'#111111',font:'baskerville',fontSize:32,align:'center',watermark:true,source:'chosen',art:[{id:'a1',asset:kind==='widget'?'olive':'cosmos',x:.5,y:kind==='widget'?.17:.2,size:kind==='widget'?.13:.19,rotation:0}]};}
export function normalizeDesign(raw,kind){const d={...defaultDesign(kind),...raw,kind,version:1};if(!FORMATS[d.format]||(kind==='widget'?!['small','medium','large'].includes(d.format):!['portrait','square','story'].includes(d.format)))d.format=kind==='widget'?'medium':'portrait';d.colors=(Array.isArray(d.colors)?d.colors:[]).slice(0,3).map(c=>/^#[0-9a-f]{6}$/i.test(c)?c:'#FFFFFF');while(d.colors.length<3)d.colors.push('#FFFFFF');d.intensity=clamp(d.intensity,0,100);d.angle=clamp(d.angle,0,360);d.fontSize=clamp(d.fontSize,22,52);d.photoShade=clamp(d.photoShade,0,70);d.photoFocus=clamp(d.photoFocus,0,100);if(!/^#[0-9a-f]{6}$/i.test(d.color))d.color='#111111';d.background=d.background==='photo'?'photo':'gradient';d.source=d.source==='daily'?'daily':'chosen';d.third=!!d.third;d.watermark=!!d.watermark;if(!FONTS[d.font])d.font='baskerville';if(!['left','center','right'].includes(d.align))d.align='center';d.art=(Array.isArray(d.art)?d.art:[]).slice(0,6).filter(a=>/^[a-z0-9-]+$/.test(a.asset||'')).map((a,i)=>({id:String(a.id||'a'+i).replace(/[^a-z0-9-]/gi,'')||'a'+i,asset:a.asset,x:clamp(a.x,.07,.93),y:clamp(a.y,.06,.94),size:clamp(a.size,.07,.5),rotation:clamp(a.rotation,-180,180)}));return d;}
export function mixWhite(hex,intensity){const t=clamp(intensity,0,100)/100;return '#'+hex.slice(1).match(/../g).map(v=>Math.round(255*(1-t)+parseInt(v,16)*t).toString(16).padStart(2,'0')).join('');}
export function wrapText(text,maxWidth,measure){const lines=[];for(const para of String(text).split('\n')){let line='';for(const word of para.split(/\s+/).filter(Boolean)){if(measure(word)>maxWidth){if(line){lines.push(line);line='';}let part='';for(const char of Array.from(word)){if(part&&measure(part+char)>maxWidth){lines.push(part);part=char;}else part+=char;}line=part;}else if(line&&measure(line+' '+word)>maxWidth){lines.push(line);line=word;}else line=line?line+' '+word:word;}lines.push(line);}return lines;}
